from . import point as pt

POINTS = [
pt('A1', 'genre', ('Le genre et les articles',
 "Les noms sont masculins ou féminins. En général, -o est masculin (el libro) et -a féminin (la casa) ; exceptions courantes : el día, el problema, la mano.\nArticles définis : el, la, los, las. Indéfinis : un, una, unos, unas.\nContractions obligatoires : a + el = al, de + el = del."),
 ('Gender and articles',
 "Nouns are masculine or feminine. Usually -o is masculine (el libro) and -a feminine (la casa); common exceptions: el día, el problema, la mano.\nDefinite articles: el, la, los, las. Indefinite: un, una, unos, unas.\nCompulsory contractions: a + el = al, de + el = del."),
 [("El libro está en la mesa.", "Le livre est sur la table.", "The book is on the table."), ("Voy al mercado.", "Je vais au marché.", "I am going to the market.")],
 r"\b(el|la|los|las)\b", ['el', 'la', 'los', 'las']),
pt('A1', 'pluriel', ("Le pluriel et l'accord de l'adjectif",
 "Pluriel : voyelle + s (casa → casas), consonne + es (ciudad → ciudades), -z → -ces (luz → luces).\nL'adjectif s'accorde en genre et en nombre et se place le plus souvent après le nom : un coche rojo, dos casas rojas. Les adjectifs en -e ou en consonne ont la même forme aux deux genres (grande, fácil)."),
 ('Plurals and adjective agreement',
 "Plural: vowel + s (casa → casas), consonant + es (ciudad → ciudades), -z → -ces (luz → luces).\nAdjectives agree in gender and number and usually follow the noun: un coche rojo, dos casas rojas. Adjectives ending in -e or a consonant have one form for both genders (grande, fácil)."),
 [("Tengo dos gatos negros.", "J'ai deux chats noirs.", "I have two black cats."), ("Las flores son bonitas.", "Les fleurs sont jolies.", "The flowers are pretty.")]),
pt('A1', 'ser-estar', ('Ser et estar',
 "Deux verbes pour « être ».\n« Ser » : identité, origine, profession, caractère durable, heure. Soy francés. Es médico. Son las tres.\n« Estar » : lieu, état passager, résultat. Estoy en casa. Está cansada. La puerta está abierta.\nLe sens change selon le verbe : ser aburrido = être ennuyeux, estar aburrido = s'ennuyer."),
 ('Ser and estar',
 "Two verbs for “to be”.\n“Ser”: identity, origin, profession, lasting traits, time. Soy francés. Es médico. Son las tres.\n“Estar”: location, temporary state, result. Estoy en casa. Está cansada. La puerta está abierta.\nMeaning shifts with the verb: ser aburrido = to be boring, estar aburrido = to be bored."),
 [("Soy estudiante.", "Je suis étudiant.", "I am a student."), ("¿Dónde estás?", "Où es-tu ?", "Where are you?"), ("Estamos muy contentos.", "Nous sommes très contents.", "We are very happy.")],
 r"\b(soy|eres|es|somos|son|estoy|estás|está|estamos|están)\b", ['es', 'está', 'son', 'están', 'soy', 'estoy']),
pt('A1', 'present', ('Le présent des verbes réguliers',
 "Trois groupes : -ar, -er, -ir.\nhablar : hablo, hablas, habla, hablamos, habláis, hablan.\ncomer : como, comes, come, comemos, coméis, comen.\nvivir : vivo, vives, vive, vivimos, vivís, viven.\nLe pronom sujet est le plus souvent omis : la terminaison suffit. Négation : « no » devant le verbe (No hablo ruso)."),
 ('The present of regular verbs',
 "Three groups: -ar, -er, -ir.\nhablar: hablo, hablas, habla, hablamos, habláis, hablan.\ncomer: como, comes, come, comemos, coméis, comen.\nvivir: vivo, vives, vive, vivimos, vivís, viven.\nSubject pronouns are usually dropped: the ending is enough. Negative: “no” before the verb (No hablo ruso)."),
 [("Hablo español.", "Je parle espagnol.", "I speak Spanish."), ("Vivimos en Madrid.", "Nous habitons à Madrid.", "We live in Madrid."), ("No como carne.", "Je ne mange pas de viande.", "I don't eat meat.")],
 r"\b(hablo|hablas|habla|hablamos|hablan|vivo|vives|vive|vivimos|viven|como|comes|comemos|comen)\b", None),
pt('A1', 'irreguliers', ('Présent : verbes irréguliers et à diphtongue',
 "Très courants : ir (voy, vas, va, vamos, vais, van), tener (tengo, tienes, tiene, tenemos, tenéis, tienen), hacer (hago), decir (digo, dices), venir (vengo, vienes), poder (puedo), querer (quiero), saber (sé), dar (doy).\nDiphtongue sous l'accent : e → ie (pensar → pienso), o → ue (dormir → duermo), e → i (pedir → pido). Nosotros et vosotros gardent la voyelle simple : pensamos, dormimos."),
 ('Present: irregular and stem-changing verbs',
 "Very common: ir (voy, vas, va, vamos, vais, van), tener (tengo, tienes, tiene, tenemos, tenéis, tienen), hacer (hago), decir (digo, dices), venir (vengo, vienes), poder (puedo), querer (quiero), saber (sé), dar (doy).\nStem change under stress: e → ie (pensar → pienso), o → ue (dormir → duermo), e → i (pedir → pido). Nosotros and vosotros keep the plain vowel: pensamos, dormimos."),
 [("Tengo hambre.", "J'ai faim.", "I am hungry."), ("¿Puedes ayudarme?", "Peux-tu m'aider ?", "Can you help me?"), ("Voy a casa.", "Je vais à la maison.", "I am going home.")],
 r"\b(tengo|tienes|tiene|tenemos|tienen|voy|vas|va|vamos|van|puedo|puedes|puede|quiero|quieres|quiere)\b", None),
pt('A1', 'questions', ('Questions et négation',
 "La question s'écrit entre ¿ et ? ; l'ordre des mots change peu, c'est l'intonation qui compte : ¿Hablas inglés?\nMots interrogatifs, toujours accentués : qué, quién, dónde, cuándo, cómo, cuánto, por qué, cuál.\nNégations : no, nunca (jamais), nada (rien), nadie (personne). Double négation normale : No veo nada."),
 ('Questions and negation',
 "Questions are written between ¿ and ?; word order barely changes, intonation does the work: ¿Hablas inglés?\nQuestion words always carry an accent: qué, quién, dónde, cuándo, cómo, cuánto, por qué, cuál.\nNegatives: no, nunca (never), nada (nothing), nadie (nobody). Double negatives are normal: No veo nada."),
 [("¿Dónde vives?", "Où habites-tu ?", "Where do you live?"), ("No tengo nada.", "Je n'ai rien.", "I have nothing.")],
 r"(?:¿|\b)([Qq]ué|[Qq]uién|[Dd]ónde|[Cc]uándo|[Cc]ómo|[Cc]uánto|[Cc]uál)\b", ['qué', 'quién', 'dónde', 'cuándo', 'cómo', 'cuánto']),
pt('A1', 'gustar', ('Gustar : aimer',
 "« Gustar » se construit comme « plaire » : Me gusta el café (le café me plaît). Le verbe s'accorde avec la chose aimée : Me gustan los gatos.\nPronoms : me, te, le, nos, os, les. Pour préciser ou insister : A mí me gusta, a Juan le gusta.\nMême construction : encantar, doler, interesar, parecer."),
 ('Gustar: to like',
 "“Gustar” works like “to please”: Me gusta el café (coffee pleases me). The verb agrees with the thing liked: Me gustan los gatos.\nPronouns: me, te, le, nos, os, les. To clarify or stress: A mí me gusta, a Juan le gusta.\nSame pattern: encantar, doler, interesar, parecer."),
 [("Me gusta la música.", "J'aime la musique.", "I like music."), ("¿Te gustan los perros?", "Aimes-tu les chiens ?", "Do you like dogs?")],
 r"\b(gusta|gustan)\b", ['gusta', 'gustan', 'gusto', 'gustas']),
pt('A2', 'possessifs-demonstratifs', ('Possessifs et démonstratifs',
 "Possessifs : mi, tu, su, nuestro/a, vuestro/a, su (pluriel : mis, tus, sus…). « Su » vaut pour son, sa, leur, votre.\nDémonstratifs, trois degrés d'éloignement : este / esta (ici), ese / esa (là), aquel / aquella (là-bas). Neutres pour une idée : esto, eso, aquello."),
 ('Possessives and demonstratives',
 "Possessives: mi, tu, su, nuestro/a, vuestro/a, su (plural: mis, tus, sus…). “Su” covers his, her, its, their and formal your.\nDemonstratives have three distances: este / esta (here), ese / esa (there), aquel / aquella (over there). Neuter forms for an idea: esto, eso, aquello."),
 [("Este es mi hermano.", "Voici mon frère.", "This is my brother."), ("¿Qué es eso?", "Qu'est-ce que c'est que ça ?", "What is that?")],
 r"\b(este|esta|ese|esa|esto|eso)\b", ['este', 'esta', 'ese', 'esa', 'esto', 'eso']),
pt('A2', 'ir-a', ('Le futur proche et le gérondif',
 "Futur proche : ir a + infinitif. Voy a comer = je vais manger.\nAction en cours : estar + gérondif (-ando pour -ar, -iendo pour -er / -ir). Estoy trabajando. Está lloviendo.\nPassé récent : acabar de + infinitif. Acabo de llegar = je viens d'arriver."),
 ('Near future and the gerund',
 "Near future: ir a + infinitive. Voy a comer = I am going to eat.\nAction in progress: estar + gerund (-ando for -ar, -iendo for -er / -ir). Estoy trabajando. Está lloviendo.\nRecent past: acabar de + infinitive. Acabo de llegar = I have just arrived."),
 [("Vamos a salir esta noche.", "Nous allons sortir ce soir.", "We are going to go out tonight."), ("¿Qué estás haciendo?", "Qu'es-tu en train de faire ?", "What are you doing?")],
 r"\b(?:estoy|estás|está|estamos|están) (\w+(?:ando|iendo))\b", None),
pt('A2', 'preterito', ('Le passé simple (pretérito indefinido)',
 "Action achevée à un moment précis du passé. C'est le temps courant du récit, y compris à l'oral.\n-ar : hablé, hablaste, habló, hablamos, hablasteis, hablaron.\n-er / -ir : comí, comiste, comió, comimos, comisteis, comieron.\nIrréguliers fréquents : ser / ir (fui, fuiste, fue, fuimos, fueron), tener (tuve), estar (estuve), hacer (hice, hizo), decir (dije), poder (pude), venir (vine)."),
 ('The preterite',
 "A completed action at a definite moment in the past. It is the everyday narrative tense, in speech too.\n-ar: hablé, hablaste, habló, hablamos, hablasteis, hablaron.\n-er / -ir: comí, comiste, comió, comimos, comisteis, comieron.\nCommon irregulars: ser / ir (fui, fuiste, fue, fuimos, fueron), tener (tuve), estar (estuve), hacer (hice, hizo), decir (dije), poder (pude), venir (vine)."),
 [("Ayer comí paella.", "Hier j'ai mangé de la paella.", "Yesterday I ate paella."), ("Fuimos al cine.", "Nous sommes allés au cinéma.", "We went to the cinema.")],
 r"\b(fui|fue|fuimos|fueron|tuve|tuvo|hice|hizo|dije|dijo|pude|pudo|vino)\b", None),
pt('A2', 'imperfecto', ("L'imparfait et son emploi face au passé simple",
 "-ar : hablaba, hablabas, hablaba, hablábamos, hablabais, hablaban. -er / -ir : comía, comías, comía, comíamos, comíais, comían. Trois irréguliers seulement : ser (era), ir (iba), ver (veía).\nL'imparfait décrit le décor, l'habitude, l'action en cours ; le passé simple, l'événement qui survient : Cuando era niño, vivía en Lima. Leía cuando sonó el teléfono."),
 ('The imperfect, and how it contrasts with the preterite',
 "-ar: hablaba, hablabas, hablaba, hablábamos, hablabais, hablaban. -er / -ir: comía, comías, comía, comíamos, comíais, comían. Only three irregulars: ser (era), ir (iba), ver (veía).\nThe imperfect sets the scene, describes habits and ongoing actions; the preterite marks the event that happens: Cuando era niño, vivía en Lima. Leía cuando sonó el teléfono."),
 [("Cuando era joven, jugaba al fútbol.", "Quand j'étais jeune, je jouais au football.", "When I was young, I played football."), ("Hacía frío.", "Il faisait froid.", "It was cold.")],
 r"\b(era|eran|estaba|estaban|tenía|tenían|había|iba|iban|hacía)\b", None),
pt('A2', 'pronoms-objet', ('Les pronoms compléments',
 "Directs : me, te, lo / la, nos, os, los / las. Indirects : me, te, le, nos, os, les.\nIls se placent avant le verbe conjugué (Lo veo) ou se collent à l'infinitif, au gérondif et à l'impératif affirmatif (Quiero verlo. Dímelo).\nIndirect + direct : l'indirect vient d'abord, et le / les devient « se » devant lo / la : Se lo doy."),
 ('Object pronouns',
 "Direct: me, te, lo / la, nos, os, los / las. Indirect: me, te, le, nos, os, les.\nThey go before the conjugated verb (Lo veo) or attach to an infinitive, gerund or affirmative command (Quiero verlo. Dímelo).\nIndirect + direct: the indirect comes first, and le / les becomes “se” before lo / la: Se lo doy."),
 [("No lo sé.", "Je ne le sais pas.", "I don't know (it)."), ("Te lo digo mañana.", "Je te le dis demain.", "I'll tell you tomorrow.")],
 r"\b(lo|la|los|las|le|les) (?:sé|veo|tengo|quiero|dije|dijo|conozco|puedo|doy|hice|vi)\b", ['lo', 'la', 'le', 'les', 'los', 'las']),
pt('A2', 'por-para', ('Por et para',
 "« Para » : but, destinataire, destination, échéance. Es para ti. Estudio para aprender. Salgo para Madrid. Para el lunes.\n« Por » : cause, moyen, durée, échange, lieu traversé, agent du passif. Gracias por todo. Por teléfono. Por la mañana. Pagué diez euros por el libro."),
 ('Por and para',
 "“Para”: purpose, recipient, destination, deadline. Es para ti. Estudio para aprender. Salgo para Madrid. Para el lunes.\n“Por”: cause, means, duration, exchange, movement through, passive agent. Gracias por todo. Por teléfono. Por la mañana. Pagué diez euros por el libro."),
 [("Este regalo es para ti.", "Ce cadeau est pour toi.", "This present is for you."), ("Gracias por tu ayuda.", "Merci pour ton aide.", "Thanks for your help.")],
 r"\b(por|para)\b", ['por', 'para']),
pt('B1', 'perfecto', ('Le passé composé (pretérito perfecto)',
 "haber au présent + participe : he, has, ha, hemos, habéis, han + hablado / comido / vivido. Le participe est invariable et ne se sépare pas de haber.\nParticipes irréguliers : hecho, dicho, visto, escrito, puesto, vuelto, abierto, muerto, roto.\nEn Espagne, on l'emploie pour une période non terminée (hoy, esta semana) ; en Amérique, le passé simple le remplace souvent."),
 ('The present perfect',
 "Present of haber + participle: he, has, ha, hemos, habéis, han + hablado / comido / vivido. The participle never changes and is never separated from haber.\nIrregular participles: hecho, dicho, visto, escrito, puesto, vuelto, abierto, muerto, roto.\nIn Spain it is used for an unfinished period (hoy, esta semana); in Latin America the preterite often replaces it."),
 [("He perdido las llaves.", "J'ai perdu les clés.", "I have lost the keys."), ("¿Has estado en México?", "As-tu été au Mexique ?", "Have you been to Mexico?")],
 r"\b(he|has|ha|hemos|han) (?:\w+ado|\w+ido|hecho|dicho|visto|escrito|puesto|vuelto)\b", ['he', 'has', 'ha', 'hemos', 'han']),
pt('B1', 'futur-conditionnel', ('Le futur et le conditionnel',
 "Futur : infinitif + é, ás, á, emos, éis, án (hablaré). Conditionnel : infinitif + ía, ías, ía, íamos, íais, ían (hablaría).\nMêmes radicaux irréguliers pour les deux : tendr-, pondr-, vendr-, saldr-, podr-, querr-, sabr-, har-, dir-, habr-.\nLe futur exprime aussi une supposition : Serán las diez (il doit être dix heures)."),
 ('Future and conditional',
 "Future: infinitive + é, ás, á, emos, éis, án (hablaré). Conditional: infinitive + ía, ías, ía, íamos, íais, ían (hablaría).\nBoth share the same irregular stems: tendr-, pondr-, vendr-, saldr-, podr-, querr-, sabr-, har-, dir-, habr-.\nThe future also expresses a guess: Serán las diez (it must be ten o'clock)."),
 [("Mañana lloverá.", "Demain il pleuvra.", "It will rain tomorrow."), ("Me gustaría viajar.", "J'aimerais voyager.", "I would like to travel.")],
 r"\b(gustaría|podría|podrías|sería|tendría|haría|querría|debería|deberías)\b", None),
pt('B1', 'imperatif', ("L'impératif",
 "Tú affirmatif = 3e personne du présent : habla, come, vive. Irréguliers : di, haz, ve, pon, sal, sé, ten, ven.\nUsted / ustedes et toutes les formes négatives prennent le subjonctif : hable, no hables, no comas.\nLes pronoms se collent à l'affirmatif (dámelo) et précèdent le verbe au négatif (no me lo des)."),
 ('The imperative',
 "Affirmative tú = third person present: habla, come, vive. Irregular: di, haz, ve, pon, sal, sé, ten, ven.\nUsted / ustedes and every negative command use the subjunctive: hable, no hables, no comas.\nPronouns attach to affirmative commands (dámelo) and precede negative ones (no me lo des)."),
 [("Ven aquí.", "Viens ici.", "Come here."), ("No te preocupes.", "Ne t'inquiète pas.", "Don't worry.")],
 r"^(?:¡)?(Ven|Haz|Dime|Mira|Espera|Escucha|Toma|Pon|Sal|Ten)\b", None),
pt('B1', 'subjonctif', ('Le subjonctif présent',
 "Formation : on part de la 1re personne du présent et on échange les voyelles. -ar → e (hable, hables, hable, hablemos, habléis, hablen) ; -er / -ir → a (coma, viva). Irréguliers : sea, esté, vaya, haya, sepa, dé ; tenga, haga, diga, venga, pueda.\nEmplois : souhait et volonté (Quiero que vengas), émotion (Me alegro de que estés aquí), doute (No creo que sea verdad), après para que, cuando + futur (Cuando llegues, llámame), ojalá."),
 ('The present subjunctive',
 "Formation: take the first person present and swap the vowel. -ar → e (hable, hables, hable, hablemos, habléis, hablen); -er / -ir → a (coma, viva). Irregular: sea, esté, vaya, haya, sepa, dé; tenga, haga, diga, venga, pueda.\nUses: wishes and will (Quiero que vengas), emotion (Me alegro de que estés aquí), doubt (No creo que sea verdad), after para que, cuando + future meaning (Cuando llegues, llámame), ojalá."),
 [("Quiero que vengas conmigo.", "Je veux que tu viennes avec moi.", "I want you to come with me."), ("Espero que estés bien.", "J'espère que tu vas bien.", "I hope you are well.")],
 r"\bque (?:\w+ )?(sea|seas|estés|esté|vengas|venga|tengas|tenga|hagas|haga|vayas|vaya|puedas|pueda|sepas|digas)\b", None),
pt('B1', 'relatives-comparaison', ('Comparer et relier',
 "Comparatif : más … que, menos … que, tan … como (aussi … que), tanto/a … como (autant de). Irréguliers : mejor, peor, mayor, menor. Superlatif : el más alto de la clase ; -ísimo (carísimo).\nRelatifs : que (le plus courant), quien (personnes, après préposition), donde, lo que (ce que)."),
 ('Comparing and linking',
 "Comparative: más … que, menos … que, tan … como (as … as), tanto/a … como (as much / many … as). Irregular: mejor, peor, mayor, menor. Superlative: el más alto de la clase; -ísimo (carísimo).\nRelatives: que (the default), quien (people, after a preposition), donde, lo que (what)."),
 [("Es más alto que yo.", "Il est plus grand que moi.", "He is taller than me."), ("No entiendo lo que dices.", "Je ne comprends pas ce que tu dis.", "I don't understand what you are saying.")],
 r"\b(más|menos|mejor|peor|tan)\b(?=.*\b(?:que|como)\b)", ['más', 'menos', 'mejor', 'peor', 'tan']),
pt('B2', 'subjonctif-imparfait', ("Le subjonctif imparfait et l'hypothèse",
 "Formé sur la 3e personne du pluriel du passé simple : hablaron → hablara, hablaras, hablara, habláramos, hablarais, hablaran (ou -se : hablase). Tuvieron → tuviera, fueron → fuera.\nHypothèse irréelle : si + subjonctif imparfait, conditionnel. Si tuviera dinero, viajaría.\nIrréel du passé : Si hubiera sabido, habría venido.\nJamais de présent du subjonctif ni de conditionnel après « si »."),
 ('The imperfect subjunctive and unreal conditions',
 "Built on the third person plural of the preterite: hablaron → hablara, hablaras, hablara, habláramos, hablarais, hablaran (or -se: hablase). Tuvieron → tuviera, fueron → fuera.\nUnreal condition: si + imperfect subjunctive, conditional. Si tuviera dinero, viajaría.\nUnreal past: Si hubiera sabido, habría venido.\nNever use the present subjunctive or the conditional after “si”."),
 [("Si fuera rico, compraría una casa.", "Si j'étais riche, j'achèterais une maison.", "If I were rich, I would buy a house.")],
 r"\b[Ss]i (?:\w+ )?(fuera|fueras|tuviera|tuvieras|pudiera|pudieras|hubiera|hubieras|estuviera|supiera)\b", None),
pt('B2', 'passif-se', ('Le passif et « se »',
 "Passif : ser + participe accordé + por. La casa fue construida por mi abuelo. Il est peu fréquent à l'oral.\nOn préfère « se » : Se habla español (on parle espagnol). Se venden pisos. Se dice que…\n« Se » sert aussi aux verbes pronominaux (levantarse) et à l'involontaire : Se me olvidó (j'ai oublié)."),
 ('The passive and “se”',
 "Passive: ser + agreeing participle + por. La casa fue construida por mi abuelo. It is uncommon in speech.\nSpanish prefers “se”: Se habla español (Spanish is spoken). Se venden pisos. Se dice que…\n“Se” also marks reflexive verbs (levantarse) and accidental events: Se me olvidó (I forgot)."),
 [("Aquí se habla español.", "Ici on parle espagnol.", "Spanish is spoken here."), ("Se me cayó el vaso.", "Le verre m'est tombé des mains.", "I dropped the glass.")],
 r"\b([Ss]e) (?:habla|dice|puede|vende|venden|necesita|sabe|usa)\b", ['se', 'le', 'lo', 'me']),
]

POINTS.insert(0, pt('A1', 'prononciation', ("Prononciation et accent écrit",
 "L'espagnol se lit comme il s'écrit. Cinq voyelles pures : a, e, i, o, u (jamais de nasale).\nc devant e / i et z : « th » anglais en Espagne, « s » en Amérique (cielo, zapato). j, et g devant e / i : son guttural, comme le « ch » allemand de Bach (jamón, gente). g devant a, o, u : g dur ; gue, gui : le u ne se prononce pas.\nh est muet (hola). ll et y : comme « y » de « yeux ». ñ : comme « gn » (año). b et v se prononcent pareil.\nr simple : un battement de langue ; rr et r initial : roulé (pero / perro).\nAccent tonique : sur l'avant-dernière syllabe si le mot finit par une voyelle, n ou s (casa, hablan) ; sinon sur la dernière (hablar, ciudad). L'accent écrit signale les exceptions (café, árbol) et distingue des mots (sí / si, él / el)."),
 ('Pronunciation and written accents',
 "Spanish is read as it is written. Five pure vowels: a, e, i, o, u.\nc before e / i and z: like English “th” in Spain, “s” in Latin America (cielo, zapato). j, and g before e / i: a throaty sound, like Scottish “loch” (jamón, gente). g before a, o, u: hard g; in gue, gui the u is silent.\nh is silent (hola). ll and y: like “y” in “yes”. ñ: like “ny” in “canyon” (año). b and v sound the same.\nSingle r: one tap of the tongue; rr and initial r: rolled (pero / perro).\nStress: on the second-to-last syllable if the word ends in a vowel, n or s (casa, hablan); otherwise on the last (hablar, ciudad). The written accent marks exceptions (café, árbol) and tells words apart (sí / si, él / el)."),
 [("El perro come jamón.", "Le chien mange du jambon.", "The dog eats ham."), ("La ciudad es grande.", "La ville est grande.", "The city is big.")]))
